// Valida o payload recebido e extrai os campos necessários
const body = $json;

if (!body.client_id) {
  return [{ json: { valid: false, error: 'client_id ausente no payload' } }];
}

if (!body.supabase_url || !body.service_key) {
  return [{ json: {
    valid: false,
    client_id: body.client_id,
    error: 'supabase_url ou service_key ausente — Banco B não configurado'
  } }];
}

return [{ json: {
  valid: true,
  client_id:    body.client_id,
  client_name:  body.client_name || body.client_id,
  supabase_url: body.supabase_url,
  anon_key:     body.anon_key,
  service_key:  body.service_key,
  org_id:       body.org_id,
  max_users:    body.max_users || 3,
  plan_name:    body.plan_name || 'Incluído'
} }];

// Avalia resultado do provision-client-db
const schemaResult = $json;
const clientId = $('validate_payload').first().json.client_id;

const schemaOk = schemaResult.success === true || schemaResult.applied === true;
const schemaError = schemaResult.error || null;

return [{ json: {
  client_id:    clientId,
  schema_ok:    schemaOk,
  schema_error: schemaError,
  schema_result: schemaResult
} }];

